const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const text = buf.toString('utf8').replace(/\r\n/g, '\n');
  const fileName = items[i].binary.data.fileName;

  const titleMatch = text.match(/^# (.+)$/m);
  const docTitle = titleMatch ? titleMatch[1].trim() : fileName;

  // split on "## " headings; the first piece is the title/header lines, so drop it
  const sections = text.split(/^## /m).slice(1);

  sections.forEach((section, idx) => {
    const newline = section.indexOf('\n');
    const heading = section.slice(0, newline).trim();
    const body = section.slice(newline + 1).trim();

    // the question list is kept for testing later, not stored as a searchable chunk
    if (heading.toLowerCase().startsWith('questions this document answers')) return;

    out.push({
      json: {
        text: `${docTitle} - ${heading}\n\n${body}`,
        metadata: {
          source: fileName,
          doc_title: docTitle,
          section: heading,
          chunk_index: idx,
          synthetic: true
        }
      }
    });
  });
}

return out;

const chunk = $('Split into chunks').item.json;
const values = $json.embedding.values;

if (values.length !== 3072) {
  throw new Error(`Expected 3072 numbers, got ${values.length}`);
}

return {
  json: {
    text: chunk.text,
    metadata: chunk.metadata,
    embedding: '[' + values.join(',') + ']'
  }
};
